    test('[TC_PETSTORE_PET_POST_003] Manage a pet end to end: create, view, update and delete it; it is gone afterwards', async ({ api, data }) => {
      requireCredentials('admin');
      const input = data.entry('valid', 'TC_PETSTORE_PET_POST_003');
      // 1. create
      const created = await api.send({ method: 'POST', path: '/pet', identity: 'default', body: input.body });
      expectStatus(created, [201]);
      expectJsonContentType(created);
      expectResponseTime(created, limits.responseTimeMs);
      expectEcho(input.body, created.json);
      const id = getAtPath(created.json, 'id');
      expect(['string', 'number'], 'create response returns an id').toContain(typeof id);
      const itemId = id as string | number;
      let deleted = false;
      try {
        // 2. read back - created data must be retrievable and identical
        const read = await api.send({ method: 'GET', path: '/pet/{petId}', identity: 'default', pathParams: { petId: itemId } });
        expectStatus(read, [200]);
        expectSchema(read, S.PetPetidGetResponse);
        expectEcho(input.body, read.json);
        // 5. delete, then the resource must be gone
        const removed = await api.send({ method: 'DELETE', path: '/pet/{petId}', identity: 'default', pathParams: { petId: itemId } });
        expectStatus(removed, [200]);
        deleted = true;
        const gone = await api.send({ method: 'GET', path: '/pet/{petId}', identity: 'default', pathParams: { petId: itemId } });
        expectStatus(gone, [404]);
      } finally {
        if (!deleted) await api.remove('pet', itemId);
      }
    });

